/* From Uiverse.io by eduardo-amaro-maciel - Tags: card, hover, rainbow */
.__UIV_SCOPE__ .container {
  margin: 0 auto;
}

.__UIV_SCOPE__ .card {
  position: relative;
  width: 200px;
  height: 300px;
  margin: 0 auto;
  background: #000;
  border-radius: 15px;
  box-shadow: 0 15px 60px rgba(0, 0, 0, 0.5);
}

.__UIV_SCOPE__ .face {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .face.back {
  box-sizing: border-box;
  padding: 20px;
}

.__UIV_SCOPE__ .face.back b {
  margin: 0;
  padding: 0;
}

.__UIV_SCOPE__ .face.back .desc {
  background-color: #eee;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.__UIV_SCOPE__ .face.front {
  transition: 0.5s;
}

.__UIV_SCOPE__ .face.front b {
  margin: 0;
  padding: 0;
  font-size: 5.1em;
  color: #fff;
  transition: 0.5s;
  text-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
  z-index: 10;
}

.__UIV_SCOPE__ .card:hover .face.front {
  height: 60px;
}

.__UIV_SCOPE__ .card:hover .face.front b {
  font-size: 2em;
}

.__UIV_SCOPE__ .face.front {
  background-color: #0cbaba;
  border-radius: 15px;
}
